  templateId: 'vibekit-claude'  // Use appropriate template for each agent
});

// Claude Agent
const claudeVibekit = new VibeKit()
  .withAgent({
    type: 'claude',
    provider: 'anthropic',
    apiKey: process.env.ANTHROPIC_API_KEY,
